import { sql } from 'drizzle-orm';
import {
    bigint,
    check,
    index,
    integer,
    jsonb,
    pgTable,
    primaryKey,
    text,
    timestamp,
} from 'drizzle-orm/pg-core';

import { user } from './auth-schema';

// Auth tables (user/session/account/verification) are generated by the
// Better Auth CLI — see auth-schema.ts. Everything app-specific lives here.
export * from './auth-schema';

/**
 * A saved Studio conversation: the whole client document (transcript, widgets
 * with their CSV, activity, pins, layout, theme, notes…) as one JSON
 * document, plus the columns the history list needs without unpacking it.
 * `agentSessionId` is the agent's server-side conversation, so a reopened
 * conversation resumes with its context.
 */
export const conversation = pgTable(
    'conversation',
    {
        // Client-minted UUID (the conversation id the Studio already uses).
        id: text('id').primaryKey(),
        userId: text('user_id')
            .notNull()
            .references(() => user.id, { onDelete: 'cascade' }),
        title: text('title').notNull(),
        agentSessionId: text('agent_session_id'),
        turnCount: integer('turn_count').default(0).notNull(),
        data: jsonb('data').notNull(),
        createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
        updatedAt: timestamp('updated_at', { withTimezone: true }).defaultNow().notNull(),
    },
    (table) => [index('conversation_user_updated_idx').on(table.userId, table.updatedAt)],
);

export type ConversationRow = typeof conversation.$inferSelect;

/**
 * A public share: a frozen copy of a conversation (or its canvas, or one
 * card) under a short id — what /s/<id> and /embed/<id> render. Read-only by
 * construction: it's a snapshot, the owner's conversation keeps evolving.
 */
export const share = pgTable(
    'share',
    {
        // Short URL-safe id (8 chars).
        id: text('id').primaryKey(),
        // Null for a search shared without an account (the search is public).
        userId: text('user_id').references(() => user.id, { onDelete: 'cascade' }),
        // What the link shows: 'conversation' (chat + canvas), 'canvas',
        // 'card', or 'search' (a search result).
        kind: text('kind').notNull(),
        // Search only: 'live' re-runs the stored definitions on every open,
        // 'snapshot' serves the bytes captured when the link was made.
        mode: text('mode'),
        conversationId: text('conversation_id'),
        cardId: text('card_id'),
        title: text('title').notNull(),
        data: jsonb('data').notNull(),
        createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
    },
    (table) => [index('share_user_idx').on(table.userId)],
);

/**
 * One row per part of a search share, in part order: what the user asked
 * (`variable_text`) and the dataset it resolved to — the definition's
 * `spec_id` and `identity`, enough to replay it through `dataset_resubmit`
 * without the language model. `operations` holds what the question asked
 * of the part beyond its data (empty for none), which the replay carries
 * back so the part keeps its operation strip. A snapshot share also carries
 * the `content_version` it captured and the `artifact_digest` of the file it
 * pinned, which the share's download link serves.
 */
export const shareRef = pgTable(
    'share_ref',
    {
        shareId: text('share_id')
            .notNull()
            .references(() => share.id, { onDelete: 'cascade' }),
        partIndex: integer('part_index').notNull(),
        specId: text('spec_id').notNull(),
        identity: jsonb('identity').notNull(),
        variableText: text('variable_text'),
        resolvedStatVarDcids: jsonb('resolved_stat_var_dcids'),
        contentVersion: text('content_version'),
        // Null for a live share and for snapshots stored before the column.
        artifactDigest: text('artifact_digest'),
        operations: jsonb('operations').notNull().default([]),
    },
    (table) => [primaryKey({ columns: [table.shareId, table.partIndex] })],
);

export type ShareRefRow = typeof shareRef.$inferSelect;

/**
 * One row per (user, roadmap entry) vote: the "Under consideration" items
 * on /data/roadmap, which only signed-in people can vote for. The entry id
 * is the corpus' own, so a re-synced roadmap keeps its votes.
 */
export const roadmapVote = pgTable(
    'roadmap_vote',
    {
        userId: text('user_id')
            .notNull()
            .references(() => user.id, { onDelete: 'cascade' }),
        entryId: text('entry_id').notNull(),
        createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
    },
    (table) => [
        primaryKey({ columns: [table.userId, table.entryId] }),
        index('roadmap_vote_entry_idx').on(table.entryId),
    ],
);

export type RoadmapVoteRow = typeof roadmapVote.$inferSelect;

export type ShareRow = typeof share.$inferSelect;

/**
 * A feedback submission (POST /api/feedback): the chat's thumbs-up/down box
 * and the site-wide form. Deliberately not referencing `user` — the form is
 * open to signed-out visitors, and `email` is whatever the visitor typed,
 * optional and unverified.
 */
export const feedback = pgTable(
    'feedback',
    {
        id: bigint('id', { mode: 'number' }).generatedAlwaysAsIdentity().primaryKey(),
        createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
        message: text('message').notNull(),
        email: text('email'),
        page: text('page'),
        userAgent: text('user_agent'),
    },
    (table) => [
        check('feedback_message_length', sql`char_length(${table.message}) BETWEEN 1 AND 5000`),
        index('feedback_created_at_idx').on(table.createdAt.desc()),
    ],
);

export type FeedbackRow = typeof feedback.$inferSelect;

/**
 * One usage event (see src/lib/events): what was searched, what a Studio
 * turn produced, a sign-in… `name` is dotted (`search.query`), `props` the
 * event's own fields. Identity is loose on purpose: `userId` when signed
 * in (no FK — the row outlives the account), `visitorId` a random
 * browser id otherwise. No IPs, no prompt text.
 */
export const event = pgTable(
    'event',
    {
        id: bigint('id', { mode: 'number' }).generatedAlwaysAsIdentity().primaryKey(),
        createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
        name: text('name').notNull(),
        userId: text('user_id'),
        visitorId: text('visitor_id'),
        page: text('page'),
        props: jsonb('props').$type<Record<string, unknown>>().default({}).notNull(),
    },
    (table) => [
        index('event_created_at_idx').on(table.createdAt.desc()),
        index('event_name_created_at_idx').on(table.name, table.createdAt.desc()),
    ],
);

export type EventRow = typeof event.$inferSelect;
